import numpy as np

class SimpleMemory:
    def __init__(self):
        self.items = []   # (向量, 文本)

    def add(self, text, vec):
        self.items.append((vec, text))

    def search(self, q_vec, top_k=2):
        def cosine(a, b):
            return np.dot(a, b) / (np.linalg.norm(a) * np.linalg.norm(b))
        scored = sorted(self.items, key=lambda x: cosine(q_vec, x[0]), reverse=True)
        return [t for _, t in scored[:top_k]]

    def recent_context(self, n=3):
        # 返回最近 n 条作为短期记忆
        return [t for _, t in self.items[-n:]]

# 示意：加入记忆并检索
mem = SimpleMemory()
mem.add("用户喜欢用 Python", np.array([0.9, 0.2]))
mem.add("用户偏好简洁回答", np.array([0.3, 0.9]))
print("最近记忆:", mem.recent_context(2))
print("相关检索:", mem.search(np.array([0.8, 0.3]), top_k=1))

