class Workflow:
    def __init__(self):
        self.steps = []   # 依次执行的步骤

    def add(self, name, fn):
        self.steps.append((name, fn))
        return self

    def run(self, x):
        state = x
        for name, fn in self.steps:
            state = fn(state)
            print(f"执行步骤 [{name}]", state)
        return state

# 定义几个简单步骤
def step1(x):
    return x + 1

def step2(x):
    return x * 2

def step3(x):
    return f"结果: {x}"

wf = Workflow()
wf.add("加1", step1).add("翻倍", step2).add("格式化", step3)
print(wf.run(3))   # 输出 结果: 8

